procedure parse_message_header(
    ghost buffer: seq<byte>,
    in rdi: nat64,
    out rax: nat64,
    out rbx: nat32,
    out rcx: nat32
)
    requires 0 <= rdi;
    requires |buffer| >= rdi + 16;
    modifies rax, rbx, rcx;
    ensures rax == u64(sub(buffer, rdi, 8));
    ensures rbx == u32(sub(buffer, rdi + 8, 4));
    ensures rcx == u32(sub(buffer, rdi + 12, 4));
{
    rax := Mem64[rdi];
    rbx := Mem32[rdi + 8];
    rcx := Mem32[rdi + 12];
}

procedure parse_and_get_payload_ptr(
    ghost buffer: seq<byte>,
    in rdi: nat64,
    in rsi: nat64,
    out rax: nat64,
    out rbx: nat32
)
    requires 0 <= rdi;
    requires rdi <= rsi;
    requires |buffer| == rsi as int;
    modifies rax, rbx, rcx, rdx;
    ensures rax == 0 ==>
       !(rdi + 16 <= rsi && rdi + 16 + (u32_to_u64(u32(sub(buffer, rdi + 8, 4)))) <= rsi);
    ensures rax != 0 ==>
        rbx == u32(sub(buffer, rdi + 8, 4)) &&
        rax == rdi + 16 &&
        rax + (u32_to_u64(rbx)) <= rsi;
{
    var header_end: nat64;
    var carry: bool;
    carry, header_end := Add(rdi, 16);
    if carry || header_end > rsi {
        rax := 0;
        rbx := 0;
        return;
    }

    var msg_id: nat64;
    var msg_type: nat32;
    parse_message_header(buffer, rdi, msg_id, rbx, msg_type);

    var payload_len: nat64 := u32_to_u64(rbx);
    var full_message_end: nat64;
    carry, full_message_end := Add(header_end, payload_len);
    if carry || full_message_end > rsi {
        rax := 0;
        return;
    }

    rax := header_end;
}

procedure copy_verified_payload(
    ghost src_buffer: seq<byte>,
    ghost dst_buffer: seq<byte>,
    in rdi: nat64,
    in rsi: nat64,
    in rdx: nat64,
    in rcx: nat64
)
    requires 0 <= rdi && rdi <= rdx;
    requires 0 <= rsi && rsi <= rcx;
    requires |src_buffer| == rdx as int;
    requires |dst_buffer| == rcx as int;
    modifies rax, rbx, r8, r9, r10, r11;
{
    var payload_ptr: nat64;
    var payload_len: nat32;

    parse_and_get_payload_ptr(src_buffer, rdi, rdx, payload_ptr, payload_len);

    if payload_ptr != 0 {
        var len64: nat64 := u32_to_u64(payload_len);
        var dst_end: nat64;
        var carry: bool;
        carry, dst_end := Add(rsi, len64);

        if !carry && dst_end <= rcx {
            var count: nat64 := 0;
            r8 := 0;
            r9 := payload_ptr;
            r10 := rsi;
            while r8 < len64
                invariant 0 <= r8 && r8 <= len64;
                invariant r9 == payload_ptr + r8;
                invariant r10 == rsi + r8;
            {
                var temp_byte: byte;
                temp_byte := Mem8[r9];
                Mem8[r10] := temp_byte;
                r8 := r8 + 1;
                r9 := r9 + 1;
                r10 := r10 + 1;
            }
        }
    }
