%struct.JadeParams = type { i32, i32 }

define void @Jade_selective_scan_step(
  %struct.JadeParams* noalias nocapture readonly %params,
  float* noalias nocapture readonly %x_t,
  float* noalias nocapture readonly %h_prev,
  float* noalias nocapture writeonly %h_out,
  float* noalias nocapture writeonly %y_out,
  float* noalias nocapture readonly %A_base,
  float* noalias nocapture readonly %B_proj,
  float* noalias nocapture readonly %C_proj,
  float* noalias nocapture readonly %delta_proj
) #0 {
entry:
  %d_model_ptr = getelementptr inbounds %struct.JadeParams, %struct.JadeParams* %params, i32 0, i32 0
  %d_model = load i32, i32* %d_model_ptr, align 4, !range !0
  %d_state_ptr = getelementptr inbounds %struct.JadeParams, %struct.JadeParams* %params, i32 0, i32 1
  %d_state = load i32, i32* %d_state_ptr, align 4, !range !0
  br label %outer.loop.header

outer.loop.header:
  %i = phi i32 [ 0, %entry ], [ %i.next, %outer.loop.latch ]
  %i.cmp = icmp slt i32%i, %d_model
  br i1%i.cmp, label %outer.loop.body, label %exit

outer.loop.body:
  %delta_i_ptr = getelementptr inbounds float, float* %delta_proj, i32%i
  %delta_i = load float, float* %delta_i_ptr, align 4
  %A_base_i_ptr = getelementptr inbounds float, float* %A_base, i32%i
  %A_base_i = load float, float* %A_base_i_ptr, align 4
  %delta_A_prod = fmul float %delta_i, %A_base_i
  %A_bar_i = fadd float 1.0, %delta_A_prod

  %B_bar_i_ptr = getelementptr inbounds float, float* %B_proj, i32%i
  %B_bar_i = load float, float* %B_bar_i_ptr, align 4

  %C_i_ptr = getelementptr inbounds float, float* %C_proj, i32%i
  %C_i = load float, float* %C_i_ptr, align 4

  %vec.width = i32 8
  %num.vectors = sdiv i32%d_state, %vec.width
  %vector.loop.end.idx = mul i32%num.vectors, %vec.width

  %A_bar_vec = insertelement <8 x float> undef, float %A_bar_i, i32 0
  %A_bar_shuf = shufflevector <8 x float> %A_bar_vec, <8 x float> undef, <8 x i32> zeroinitializer
  %B_bar_vec = insertelement <8 x float> undef, float %B_bar_i, i32 0
  %B_bar_shuf = shufflevector <8 x float> %B_bar_vec, <8 x float> undef, <8 x i32> zeroinitializer

  %x_t_ptr = getelementptr inbounds float, float* %x_t, i32%i
  %x_t_val = load float, float* %x_t_ptr, align 4
  %x_t_vec_elem = insertelement <8 x float> undef, float %x_t_val, i32 0
  %x_t_shuf = shufflevector <8 x float> %x_t_vec_elem, <8 x float> undef, <8 x i32> zeroinitializer

  %idx_base = mul i32%i, %d_state
  br label %vector.loop.header

vector.loop.header:
  %j.vec.phi = phi i32 [ 0, %outer.loop.body ], [ %j.vec.next, %vector.loop.latch ]
  %vec.loop.cmp = icmp slt i32%j.vec.phi, %vector.loop.end.idx
  br i1%vec.loop.cmp, label %vector.loop.body, label %scalar.loop.header

vector.loop.body:
  %idx.vec = add i32%idx_base, %j.vec.phi
  %h_prev_vec_ptr = getelementptr inbounds float, float* %h_prev, i32%idx.vec
  %h_prev_vec = load <8 x float>, <8 x float>* %h_prev_vec_ptr, align 32

  %term1_vec = fmul <8 x float> %A_bar_shuf, %h_prev_vec
  %term2_vec = fmul <8 x float> %B_bar_shuf, %x_t_shuf
  %h_t_vec = fadd <8 x float> %term1_vec, %term2_vec

  %h_out_vec_ptr = getelementptr inbounds float, float* %h_out, i32%idx.vec
  store <8 x float> %h_t_vec, <8 x float>* %h_out_vec_ptr, align 32
  br label %vector.loop.latch

vector.loop.latch:
  %j.vec.next = add i32%j.vec.phi, %vec.width
  br label %vector.loop.header, !llvm.loop !1

scalar.loop.header:
  %acc.vec = call <8 x float> @llvm.experimental.vector.reduce.v2.fadd.v8f32(<8 x float> zeroinitializer, <8 x float> zeroinitializer)
  %y_acc = call float @llvm.experimental.vector.reduce.fadd.f32(float 0.0, <8 x float> %acc.vec)

  br label %reduction.loop.header

reduction.loop.header:
  %k = phi i32 [ 0, %scalar.loop.header ], [ %k.next, %reduction.loop.latch ]
  %acc.phi = phi float [ %y_acc, %scalar.loop.header ], [ %acc.next, %reduction.loop.latch ]
  %k.cmp = icmp slt i32%k, %d_state
  br i1%k.cmp, label %reduction.loop.body, label %reduction.loop.exit

reduction.loop.body:
  %h_t_idx = add i32%idx_base, %k
  %h_t_elem_ptr = getelementptr inbounds float, float* %h_out, i32%h_t_idx
  %h_t_elem = load float, float* %h_t_elem_ptr, align 4
  %acc.next = fadd float %acc.phi, %h_t_elem
  br label %reduction.loop.latch

reduction.loop.latch:
  %k.next = add i32%k, 1
  br label %reduction.loop.header, !llvm.loop !2

reduction.loop.exit:
  %h_t_sum = phi float [ %acc.next, %reduction.loop.latch ]
  %y_t_val = fmul float %C_i, %h_t_sum

  %y_out_ptr = getelementptr inbounds float, float* %y_out, i32%i
  store float %y_t_val, float* %y_out_ptr, align 4
  br label %outer.loop.latch

outer.loop.latch:
  %i.next = add i32%i, 1
  br label %outer.loop.header, !llvm.loop !3

exit:
  ret void
}

