    /\ proposedValue \in [Nodes -> 0..MaxValue]
    /\ votedValue \in [Nodes -> 0..MaxValue \cup {-1}]
    /\ decidedValue \in [Nodes -> 0..MaxValue \cup {-1}]
    /\ round \in [Nodes -> Nat]
    /\ messages \subseteq
        [ type: {"propose", "vote", "commit"},
          from: Nodes,
          to: Nodes,
          round: Nat,
          value: 0..MaxValue ]

Init ==
    /\ nodeState = [n \in Nodes |-> "proposing"]
    /\ \E val \in 0..MaxValue : proposedValue = [n \in Nodes |-> val]
    /\ votedValue = [n \in Nodes |-> -1]
    /\ decidedValue = [n \in Nodes |-> -1]
    /\ round = [n \in Nodes |-> 1]
    /\ messages = {}

Propose(n) ==
    /\ n \in NonFaultyNodes
    /\ nodeState[n] = "proposing"
    /\ messages' = messages \cup {
        [type |-> "propose", from |-> n, to |-> m, round |-> round[n], value |-> proposedValue[n]]
        : m \in Nodes
    }
    /\ UNCHANGED <<nodeState, proposedValue, votedValue, decidedValue, round>>

ReceiveProposalAndVote(n) ==
    /\ n \in NonFaultyNodes
    /\ \E msg \in messages:
        /\ msg.type = "propose"
        /\ msg.to = n
        /\ msg.from \in NonFaultyNodes
        /\ msg.round >= round[n]
        /\ nodeState[n] \in {"proposing", "voted"}
    /\ round' = [round EXCEPT ![n] = msg.round]
    /\ votedValue' = [votedValue EXCEPT ![n] = msg.value]
    /\ nodeState' = [nodeState EXCEPT ![n] = "voted"]
    /\ messages' = (messages \ {msg}) \cup {
        [type |-> "vote", from |-> n, to |-> m, round |-> round'[n], value |-> votedValue'[n]]
        : m \in Nodes
    }
    /\ UNCHANGED <<proposedValue, decidedValue>>

ReceiveVotesAndCommit(n) ==
    LET QuorumSize == (Cardinality(Nodes) \div 2) + 1
    IN
    /\ n \in NonFaultyNodes
    /\ nodeState[n] = "voted"
    /\ \E val \in 0..MaxValue:
        LET receivedVotes == {m.from : m \in messages |
                                /\ m.type = "vote"
                                /\ m.round = round[n]
                                /\ m.value = val
                            }
        IN Cardinality(receivedVotes) >= QuorumSize
    /\ nodeState' = [nodeState EXCEPT ![n] = "decided"]
    /\ decidedValue' = [decidedValue EXCEPT ![n] = val]
    /\ messages' = messages \cup {
        [type |-> "commit", from |-> n, to |-> m, round |-> round[n], value |-> val]
        : m \in Nodes
    }
    /\ UNCHANGED <<proposedValue, votedValue, round>>

ReceiveCommit(n) ==
    /\ n \in NonFaultyNodes
    /\ nodeState[n] /= "decided"
    /\ \E msg \in messages:
