    output                                s_axis_ready,
    input signed [DATA_WIDTH-1:0]         s_axis_x_t,
    input signed [DATA_WIDTH-1:0]         s_axis_state_prev,
    input signed [DATA_WIDTH-1:0]         s_axis_delta_t,
    input signed [TERNARY_WIDTH-1:0]      s_axis_B_t,
    input signed [TERNARY_WIDTH-1:0]      s_axis_A_static,
    input signed [TERNARY_WIDTH-1:0]      s_axis_C_t,

    output                                m_axis_valid,
