reg p1_valid, p2_valid, p3_valid, p4_valid, p5_valid;

reg signed [DATA_WIDTH-1:0] p1_x_t, p1_state_prev, p1_delta_t;
reg signed [DATA_WIDTH-1:0] p1_A_static_decoded, p1_B_t_decoded, p1_C_t_decoded;

reg signed [DATA_WIDTH*2-1:0] p2_A_term_prod;
reg signed [DATA_WIDTH*2-1:0] p2_B_term_prod;
reg signed [DATA_WIDTH-1:0] p2_state_prev;
reg signed [DATA_WIDTH-1:0] p2_C_t_decoded;

reg signed [DATA_WIDTH-1:0] p3_h_t;
reg signed [DATA_WIDTH-1:0] p3_C_t_decoded;

reg signed [DATA_WIDTH*2-1:0] p4_y_t_unactivated;

reg signed [DATA_WIDTH-1:0] p5_y_t_activated;

function signed [DATA_WIDTH-1:0] decode_ternary;
    input [TERNARY_WIDTH-1:0] t_val;
    begin
        case (t_val)
            2'b01: decode_ternary = 16'h0100;
            2'b11: decode_ternary = 16'hFF00;
            default: decode_ternary = 16'h0000;
        endcase
    end
endfunction

wire p1_ready = !p2_valid || p2_ready;
wire p2_ready = !p3_valid || p3_ready;
wire p3_ready = !p4_valid || p4_ready;
wire p4_ready = !p5_valid || p5_ready;
wire p5_ready = m_axis_ready;
assign s_axis_ready = p1_ready;
assign m_axis_valid = p5_valid;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p1_valid <= 1'b0;
    end else if (p1_ready) begin
        p1_valid <= s_axis_valid;
        if (s_axis_valid) begin
            p1_x_t <= s_axis_x_t;
            p1_state_prev <= s_axis_state_prev;
            p1_delta_t <= s_axis_delta_t;
            p1_A_static_decoded <= decode_ternary(s_axis_A_static);
            p1_B_t_decoded <= decode_ternary(s_axis_B_t);
            p1_C_t_decoded <= decode_ternary(s_axis_C_t);
