always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p2_valid <= 1'b0;
    end else if (p2_ready) begin
        p2_valid <= p1_valid;
        if (p1_valid) begin
            logic signed [DATA_WIDTH*2-1:0] temp_prod1;
            logic signed [DATA_WIDTH*2-1:0] temp_prod2;
            temp_prod1 = p1_delta_t * p1_A_static_decoded;
            temp_prod2 = (temp_prod1 >>> 8) * p1_state_prev;
            p2_A_term_prod <= temp_prod2;
            p2_B_term_prod <= p1_B_t_decoded * p1_x_t;
            p2_state_prev <= p1_state_prev;
            p2_C_t_decoded <= p1_C_t_decoded;
        end
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p3_valid <= 1'b0;
    end else if (p3_ready) begin
        p3_valid <= p2_valid;
        if (p2_valid) begin
            p3_h_t <= p2_state_prev + $signed(p2_A_term_prod >>> 16) + $signed(p2_B_term_prod >>> 8);
            p3_C_t_decoded <= p2_C_t_decoded;
        end
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p4_valid <= 1'b0;
    end else if (p4_ready) begin
        p4_valid <= p3_valid;
        if (p3_valid) begin
            p4_y_t_unactivated <= p3_C_t_decoded * p3_h_t;
        end
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p5_valid <= 1'b0;
    end else if (p5_ready) begin
        p5_valid <= p4_valid;
        if (p4_valid) begin
            logic signed [DATA_WIDTH-1:0] silu_in;
            silu_in = $signed(p4_y_t_unactivated >>> 8);

            localparam signed [DATA_WIDTH-1:0] C_NEG_4 = -4 * 256;
            localparam signed [DATA_WIDTH-1:0] C_POS_4 = 4 * 256;
            localparam signed [DATA_WIDTH-1:0] C_0_5 = 128;
            localparam signed [DATA_WIDTH-1:0] C_0_125 = 32;
            localparam signed [DATA_WIDTH-1:0] C_NEG_0_01 = -3;

            logic signed [DATA_WIDTH*2-1:0] term_x_sq_scaled = silu_in * silu_in;
            logic signed [DATA_WIDTH-1:0] term_x_sq = $signed(term_x_sq_scaled >>> 8);

            if (silu_in < C_NEG_4) begin
                p5_y_t_activated <= $signed((C_NEG_0_01 * silu_in) >>> 8);
            end else if (silu_in >= C_POS_4) begin
                p5_y_t_activated <= silu_in;
            end else begin
                p5_y_t_activated <= $signed(((C_0_125 * term_x_sq) >>> 8) + ((C_0_5 * silu_in) >>> 8));
            end
        end
    end
end

assign m_axis_h_t = p3_h_t;
assign m_axis_y_t = p5_y_t_activated;

