import Clash.Prelude

type DModel = 8192
type DState = 256

data ControlState
    = Idle
    | FetchingParams
    | FetchingState
    | Computing
    | WritingBackState
    | WritingBackOutput
    | Done
    deriving (Generic, NFDataX, Eq, Show)

data ControllerInput = ControllerInput
    { startComputation :: Bool
    , coreDone         :: Vec DState Bool
    , memoryReady      :: Bool
    } deriving (Generic, NFDataX)

data ControllerOutput = ControllerOutput
    { coreStart       :: Vec DState Bool
    , memoryReadAddr  :: Unsigned 32
    , memoryWriteAddr :: Unsigned 32
    , memoryWriteEn   :: Bool
    , computationDone :: Bool
    } deriving (Generic, NFDataX)

forgeController
    :: HiddenClockResetEnable dom
    => Signal dom ControllerInput
    -> Signal dom ControllerOutput
forgeController = mealy transition initialState
  where
    initialState = (Idle, 0, 0, 0)

transition
    :: (ControlState, Unsigned 32, Unsigned 32, Index DModel)
    -> ControllerInput
    -> ((ControlState, Unsigned 32, Unsigned 32, Index DModel), ControllerOutput)
transition (state, rAddr, wAddr, d_model_idx) ControllerInput{..} = (nextS, output)
  where
    dModelSize = fromInteger $ natVal (SNat @DModel)
    dStateSize = fromInteger $ natVal (SNat @DState)

    baseAddrParams = 0
    baseAddrState  = baseAddrParams + 3 * dModelSize
    baseAddrInput  = baseAddrState + dModelSize * dStateSize

    outputAddrState = 0
    outputAddrY     = outputAddrState + dModelSize * dStateSize

    (nextState, nextRAddr, nextWAddr, next_d_model_idx) = case state of
        Idle ->
            if startComputation
            then (FetchingParams, baseAddrParams + fromIntegral d_model_idx, 0, 0)
            else (Idle, 0, 0, 0)

        FetchingParams ->
            if memoryReady
            then (FetchingState, baseAddrState + (fromIntegral d_model_idx * dStateSize), wAddr, d_model_idx)
            else (FetchingParams, rAddr, wAddr, d_model_idx)

        FetchingState ->
            if memoryReady
            then (Computing, rAddr + dStateSize, wAddr, d_model_idx)
            else (FetchingState, rAddr, wAddr, d_model_idx)

        Computing ->
            if and coreDone
            then (WritingBackState, rAddr, outputAddrState + (fromIntegral d_model_idx * dStateSize), d_model_idx)
            else (Computing, rAddr, wAddr, d_model_idx)

        WritingBackState ->
            if memoryReady
            then (WritingBackOutput, rAddr, outputAddrY + fromIntegral d_model_idx, d_model_idx)
            else (WritingBackState, rAddr, wAddr, d_model_idx)

        WritingBackOutput ->
            if memoryReady
            then if d_model_idx == maxBound
                 then (Done, rAddr, wAddr, d_model_idx)
                 else (FetchingParams, baseAddrParams + fromIntegral(d_model_idx + 1), wAddr, d_model_idx + 1)
            else (WritingBackOutput, rAddr, wAddr, d_model_idx)

        Done ->
            if not startComputation
            then (Idle, 0, 0, 0)
            else (Done, rAddr, wAddr, d_model_idx)

    output = ControllerOutput
        { coreStart       = if nextState == Computing && state /= Computing then pure True else pure False
        , memoryReadAddr  = rAddr
        , memoryWriteAddr = wAddr
        , memoryWriteEn   = state == WritingBackState || state == WritingBackOutput
        , computationDone = state == Done
        }
    nextS = (nextState, nextRAddr, nextWAddr, next_d_model_idx)

topEntity
    :: Clock System
    -> Reset System
    -> Enable System
    -> Signal System ControllerOutput
topEntity = exposeClockResetEnable system
  where
    system clk rst en = forgeController (controllerInput clk rst en)

    controllerInput clk rst en =
        let
            startSignal = register clk rst en False (True :- pure False)
            computingStarted = isRising clk rst en False (coreStart <$> system clk rst en !! 0)
            coreDoneSignal = register clk rst en False (delayedStart clk rst en computingStarted)
            memReadyCounter = register clk rst en 0 (wrappingInc <$> memReadyCounter)
            memoryReadySignal = (== 1) <$> memReadyCounter
        in bundle (ControllerInput <$> startSignal <*> (pure <$> coreDoneSignal) <*> memoryReadySignal)

    delayedStart clk rst en = delayed clk rst en (SNat @5) False

wrappingInc :: (Eq a, Bounded a, Num a) => a -> a
wrappingInc x = if x == maxBound then 0 else x + 1

delayed
    :: (HiddenClockResetEnable dom, KnownNat d, NFDataX a)
    => Clock dom
    -> Reset dom
    -> Enable dom
    -> SNat d
    -> a
    -> Signal dom a
    -> Signal dom a
delayed clk rst en SNat initial sig = last (iterate (SNat @d) (register clk rst en initial) sig)

isRising
