from std/atomics import Atomic
from random import rand, randomize

type
  TaskPriority* = enum
    Low, Normal, High, Critical

  TaskStatus* = enum
    Pending, Running, Completed, Failed

  Task[T] = object
    id*: int
    priority*: TaskPriority
    procToRun*: proc(data: pointer): T {.gcsafe.}
    data*: pointer

  Future*[T] = ref object
    taskId*: int
    status*: Atomic[TaskStatus]
    result*: Option[T]
    error*: Option[string]
    lock*: Lock
    cond*: Cond

  WorkerThread = ref object
    id: int
    taskDeque: Deque[Task[pointer]]
    lock: Lock

  Scheduler* = ref object
    taskCounter*: Atomic[int]
    globalQueues*: array[TaskPriority, Deque[Task[pointer]]]
    futures*: Table[int, Future[pointer]]
    workers*: seq[WorkerThread]
    numThreads*: int
    active*: Atomic[bool]
    globalQueueLock*: Lock
    futuresLock*: Lock
    stats*: SchedulerStats

  SchedulerStats* = object
    tasksSubmitted*: Atomic[int]
    tasksCompleted*: Atomic[int]
    tasksFailed*: Atomic[int]
    tasksStolen*: Atomic[int]
    totalExecutionTime*: Atomic[int64]

proc initScheduler*(numThreads: int): Scheduler =
  new(result)
  result.numThreads = numThreads
  atomicStore(result.active, true)

  initLock(result.globalQueueLock)
  initLock(result.futuresLock)
  result.futures = initTable[int, Future[pointer]]()
  randomize()

  atomicStore(result.taskCounter, 0)
  atomicStore(result.stats.tasksSubmitted, 0)
  atomicStore(result.stats.tasksCompleted, 0)
  atomicStore(result.stats.tasksFailed, 0)
  atomicStore(result.stats.tasksStolen, 0)
  atomicStore(result.stats.totalExecutionTime, 0)

  for priority in TaskPriority:
    result.globalQueues[priority] = initDeque[Task[pointer]]()

  for i in 0..<numThreads:
    var worker: WorkerThread
    new(worker)
    worker.id = i
    worker.taskDeque = initDeque[Task[pointer]]()
    initLock(worker.lock)
    result.workers.add(worker)
    spawn result.workerThread(worker)

proc shutdown*(scheduler: Scheduler) =
  atomicStore(scheduler.active, false)
  sleep(200)
  dealloc(scheduler.globalQueueLock)
  dealloc(scheduler.futuresLock)
  for worker in scheduler.workers:
    dealloc(worker.lock)

proc submit*[T](scheduler: Scheduler, p: proc(data: pointer): T {.gcsafe.}, data: pointer, priority: TaskPriority = Normal): Future[T] =
  let taskId = atomicInc(scheduler.taskCounter)
  let task = Task[pointer](
    id: taskId,
    priority: priority,
    procToRun: cast[proc(data: pointer): pointer {.gcsafe.}](p),
    data: data
  )

  var future: Future[pointer]
  new(future)
  future.taskId = taskId
  atomicStore(future.status, Pending)
  initLock(future.lock)
  initCond(future.cond)

  withLock scheduler.futuresLock:
    scheduler.futures[taskId] = future

  withLock scheduler.globalQueueLock:
    scheduler.globalQueues[priority].addLast(task)

  atomicInc(scheduler.stats.tasksSubmitted)
  return cast[Future[T]](future)

proc getResult*[T](future: Future[T]): T =
  let baseFuture = cast[Future[pointer]](future)
  withLock baseFuture.lock:
    while atomicLoad(baseFuture.status) == Pending or atomicLoad(baseFuture.status) == Running:
      wait(baseFuture.cond, baseFuture.lock)

    if atomicLoad(baseFuture.status) == Failed:
      raise newException(Exception, "Task " & $baseFuture.taskId & " failed: " & $baseFuture.error.get())
    return cast[T](baseFuture.result.get())

proc getNextTask(scheduler: Scheduler, worker: WorkerThread): Option[Task[pointer]] =
  withLock worker.lock:
    if worker.taskDeque.len > 0:
      return some(worker.taskDeque.popLast())

  withLock scheduler.globalQueueLock:
    for priority in countdown(high(TaskPriority), low(TaskPriority)):
      if scheduler.globalQueues[priority].len > 0:
        return some(scheduler.globalQueues[priority].popFirst())

  let victimIndex = rand(scheduler.numThreads - 1)
  if victimIndex != worker.id:
    let victim = scheduler.workers[victimIndex]
    withLock victim.lock:
      if victim.taskDeque.len > 0:
        atomicInc(scheduler.stats.tasksStolen)
        return some(victim.taskDeque.popFirst())

  return none[Task[pointer]]()

proc executeTask(scheduler: Scheduler, task: Task[pointer]) =
  let startTime = getTime()
  let future = scheduler.futures[task.id]
  atomicStore(future.status, Running)

  try:
    let result = task.procToRun(task.data)
    withLock future.lock:
      future.result = some(result)
      atomicStore(future.status, Completed)
      signal(future.cond)
    atomicInc(scheduler.stats.tasksCompleted)
  except Exception as e:
    withLock future.lock:
      future.error = some(e.msg)
      atomicStore(future.status, Failed)
      signal(future.cond)
    atomicInc(scheduler.stats.tasksFailed)

  let endTime = getTime()
  let duration = endTime - startTime
  atomicAdd(scheduler.stats.totalExecutionTime, duration.nanoseconds)

proc workerThread(scheduler: Scheduler, worker: WorkerThread) {.thread.} =
  while atomicLoad(scheduler.active):
    let taskOpt = scheduler.getNextTask(worker)
    if taskOpt.isSome:
      scheduler.executeTask(taskOpt.get())
    else:
      sleep(10)

proc getStats*(scheduler: Scheduler): SchedulerStats =
  return scheduler.stats

