fun read_header {n:int | n >= HEADER_SIZE} (
  pf:!in_bounds(HEADER_SIZE - 1, n) | buf: buffer(n)
): header = let
  val p_id = gptr_add<byte>(buf, 0)
  val p_len = gptr_add<byte>(buf, 8)
  val p_type = gptr_add<byte>(buf, 12)
in
  @{
    id = gptr_load<msg_id_t>(p_id),
    len = gptr_load<payload_len_t>(p_len),
    mtype = gptr_load<msg_type_t>(p_type)
  }
end

