  hdr=header,
  prfpf= (region_in_bounds(n, 0, gint_of_uint(hdr.len) + HEADER_SIZE) | ())
}

fun parse_message {n:int} (
  buf: buffer(n)
): Option_vt (message(n)) =
  if n >= HEADER_SIZE then let
    prval pf_hdr = in_bounds(HEADER_SIZE - 1, n)
    val hdr = read_header (pf_hdr | buf)
    val payload_len = gint_of_uint(hdr.len)
    val required_len = payload_len + HEADER_SIZE
  in
    if required_len <= n then let
      prval () = pf_payload = region_in_bounds {n} {0} {required_len} (in_bounds(required_len - 1, n) | n, 0, required_len)
      val msg = @{ hdr = hdr, prfpf = (pf_payload | ()) }
    in
      Some_vt(msg)
    end else None_vt()
  end else None_vt()

